/*!
 * GeekHonize UI 行为层
 *
 * 通过 data-gh-* 属性声明式绑定，服务端渲染的 HTML 不需要逐页写 JS。
 *
 *   data-gh-theme-toggle              主题切换容器（内含 data-gh-theme-set 按钮）
 *   data-gh-theme-set="light|dark|auto"
 *   data-gh-nav                       主导航（.gh-nav__item[data-open]）
 *   data-gh-open="#id"                打开抽屉 / 模态
 *   data-gh-close                     关闭最近的抽屉 / 模态
 *   data-gh-dropdown                  下拉菜单容器
 *   data-gh-accordion                 折叠面板容器（.gh-accordion__item）
 *   data-gh-tabs                      标签页容器（.gh-tab[data-gh-target]）
 *   data-gh-copy="#sel"               复制目标文本
 *   data-gh-reveal                    滚动进入动画
 *   data-gh-sortable                  可排序表格
 *   data-gh-toc="#content"            文档目录滚动高亮
 *   data-gh-submit                    表单提交：自动 loading 态
 *   data-gh-soft="#main"              开启站内软导航，值为内容容器选择器
 *                                     （仅显式标注该属性的页面启用；已是 SPA
 *                                      自查路由的页面不要加，避免接管其内部渲染）
 *   data-gh-no-soft                   该链接不走软导航，强制整页跳转
 */
(function () {
  'use strict';
  var THEME_KEY = 'gh-theme';
  var THEMES = ['light', 'dark', 'auto'];
  function $(sel, root) {
    return (root || document).querySelector(sel);
  }
  function $$(sel, root) {
    return Array.prototype.slice.call((root || document).querySelectorAll(sel));
  }
  function on(el, ev, fn, opt) {
    if (el) el.addEventListener(ev, fn, opt || false);
  }
  function emit(name, detail) {
    document.dispatchEvent(new CustomEvent(name, { detail: detail }));
  }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  var theme = {
    get: function () {
      try {
        var v = localStorage.getItem(THEME_KEY);
        return THEMES.indexOf(v) >= 0 ? v : null;
      } catch (e) {
        return null;
      }
    },
    resolved: function () {
      var t = theme.get();
      if (t && t !== 'auto') return t;
      return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    },
    apply: function (value) {
      var v = THEMES.indexOf(value) >= 0 ? value : 'auto';
      document.documentElement.setAttribute('data-theme', v);
      var meta = $('meta[name="theme-color"]');
      if (meta) meta.setAttribute('content', theme.resolved() === 'dark' ? '#141414' : '#ffffff');
      $$('[data-gh-theme-set]').forEach(function (b) {
        b.setAttribute('aria-pressed', String(b.getAttribute('data-gh-theme-set') === v));
      });
      emit('gh:theme', { theme: v, resolved: theme.resolved() });
    },
    set: function (v) {
      try {
        if (v === 'auto') localStorage.removeItem(THEME_KEY);
        else localStorage.setItem(THEME_KEY, v);
      } catch (e) {
      }
      theme.apply(v);
    },
    cycle: function () {
      var cur = theme.get() || 'auto';
      theme.set(THEMES[(THEMES.indexOf(cur) + 1) % THEMES.length]);
    },
  };
  var progress = {
    el: null,
    timer: null,
    start: function () {
      if (!progress.el) {
        var bar = document.createElement('div');
        bar.className = 'gh-loadbar';
        bar.setAttribute('aria-hidden', 'true');
        bar.innerHTML = '<span class="gh-loadbar__bar"></span>';
        document.body.appendChild(bar);
        progress.el = bar;
      }
      progress.el.setAttribute('data-active', 'true');
      document.documentElement.setAttribute('data-gh-busy', 'true');
    },
    done: function () {
      if (!progress.el) return;
      progress.el.setAttribute('data-active', 'false');
      document.documentElement.removeAttribute('data-gh-busy');
    },
    wrap: function (p) {
      progress.start();
      return p.then(
        function (v) {
          progress.done();
          return v;
        },
        function (e) {
          progress.done();
          throw e;
        },
      );
    },
  };
  function closeAllNav(root) {
    $$('.gh-nav__item[data-open="true"]', root).forEach(function (i) {
      i.setAttribute('data-open', 'false');
      var t = $('.gh-nav__link', i);
      if (t) t.setAttribute('aria-expanded', 'false');
    });
  }
  function initNav(root) {
    $$('[data-gh-nav] .gh-nav__item', root).forEach(function (item) {
      var trigger = $('.gh-nav__link[data-gh-panel]', item);
      if (!trigger) return;
      trigger.setAttribute('aria-expanded', 'false');
      on(trigger, 'click', function (e) {
        e.preventDefault();
        var open = item.getAttribute('data-open') === 'true';
        closeAllNav(root);
        item.setAttribute('data-open', String(!open));
        trigger.setAttribute('aria-expanded', String(!open));
      });
      on(item, 'mouseenter', function () {
        if (window.innerWidth > 1000) {
          closeAllNav(root);
          item.setAttribute('data-open', 'true');
          trigger.setAttribute('aria-expanded', 'true');
        }
      });
      on(item, 'mouseleave', function () {
        if (window.innerWidth > 1000) {
          item.setAttribute('data-open', 'false');
          trigger.setAttribute('aria-expanded', 'false');
        }
      });
    });
  }
  function syncNavActive(root) {
    var here = location.pathname.replace(/\/+$/, '') || '/';
    $$('[data-gh-nav] a[href]', root).forEach(function (a) {
      var p;
      try {
        p = new URL(a.href, location.href).pathname.replace(/\/+$/, '') || '/';
      } catch (e) {
        return;
      }
      if (p === here) a.setAttribute('aria-current', 'page');
      else a.removeAttribute('aria-current');
    });
  }
  function openLayer(sel) {
    var el = typeof sel === 'string' ? $(sel) : sel;
    if (!el) return;
    el.setAttribute('data-open', 'true');
    document.documentElement.style.overflow = 'hidden';
    var focusable = $('[autofocus],button,input,select,textarea,a[href]', el);
    if (focusable) focusable.focus({ preventScroll: true });
    emit('gh:layeropen', { el: el });
  }
  function closeLayer(el) {
    if (!el) return;
    el.setAttribute('data-open', 'false');
    if (!$('.gh-modal[data-open="true"],.gh-drawer[data-open="true"]')) {
      document.documentElement.style.overflow = '';
    }
    emit('gh:layerclose', { el: el });
  }
  function closeAllDropdowns(root) {
    $$('[data-gh-dropdown][data-open="true"]', root).forEach(function (dd) {
      dd.setAttribute('data-open', 'false');
      var t = $('[data-gh-dropdown-trigger]', dd) || $('button', dd);
      if (t) t.setAttribute('aria-expanded', 'false');
    });
  }
  function initLayers(root) {
    $$('[data-gh-open]', root).forEach(function (b) {
      on(b, 'click', function (e) {
        e.preventDefault();
        openLayer(b.getAttribute('data-gh-open'));
      });
    });
    $$('[data-gh-close]', root).forEach(function (b) {
      on(b, 'click', function (e) {
        e.preventDefault();
        closeLayer(b.closest('.gh-modal,.gh-drawer'));
      });
    });
    $$('.gh-modal,.gh-drawer', root).forEach(function (layer) {
      on(layer, 'mousedown', function (e) {
        if (e.target === layer) closeLayer(layer);
      });
    });
    $$('[data-gh-dropdown]', root).forEach(function (dd) {
      var trigger = $('[data-gh-dropdown-trigger]', dd) || $('button', dd);
      if (!trigger) return;
      trigger.setAttribute('aria-haspopup', 'true');
      trigger.setAttribute('aria-expanded', 'false');
      on(trigger, 'click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        var open = dd.getAttribute('data-open') === 'true';
        closeAllDropdowns(root);
        dd.setAttribute('data-open', String(!open));
        trigger.setAttribute('aria-expanded', String(!open));
      });
    });
  }
  function initAccordion(root) {
    $$('[data-gh-accordion] .gh-accordion__trigger', root).forEach(function (trigger) {
      on(trigger, 'click', function () {
        var item = trigger.closest('.gh-accordion__item');
        var host = trigger.closest('[data-gh-accordion]');
        var single = host.getAttribute('data-gh-accordion') === 'single';
        var open = item.getAttribute('data-open') === 'true';
        if (single) {
          $$('.gh-accordion__item', item.parentNode).forEach(function (i) {
            i.setAttribute('data-open', 'false');
            var t = $('.gh-accordion__trigger', i);
            if (t) t.setAttribute('aria-expanded', 'false');
          });
        }
        item.setAttribute('data-open', String(!open));
        trigger.setAttribute('aria-expanded', String(!open));
      });
    });
  }
  function initTabs(root) {
    $$('[data-gh-tabs]', root).forEach(function (group) {
      var tabs = $$('.gh-tab', group);
      tabs.forEach(function (tab, idx) {
        on(tab, 'click', function () {
          tabs.forEach(function (t) {
            t.setAttribute('aria-selected', 'false');
            var p = document.getElementById(t.getAttribute('data-gh-target') || '');
            if (p) p.hidden = true;
          });
          tab.setAttribute('aria-selected', 'true');
          var panel = document.getElementById(tab.getAttribute('data-gh-target') || '');
          if (panel) panel.hidden = false;
          emit('gh:tab', { index: idx, id: tab.getAttribute('data-gh-target') });
        });
      });
    });
  }
  function initCopy(root) {
    $$('[data-gh-copy]', root).forEach(function (btn) {
      on(btn, 'click', function () {
        var sel = btn.getAttribute('data-gh-copy');
        var target = sel ? $(sel) : btn.closest('.gh-codeblock') && $('pre', btn.closest('.gh-codeblock'));
        var text = target ? target.innerText : '';
        if (!text) return;
        var done = function (ok) {
          toast(ok ? '已复制' : '复制失败，请手动选择', ok ? 'success' : 'danger');
        };
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(text).then(function () {
            done(true);
          }, function () {
            done(false);
          });
        } else {
          try {
            var ta = document.createElement('textarea');
            ta.value = text;
            ta.style.position = 'fixed';
            ta.style.opacity = '0';
            document.body.appendChild(ta);
            ta.select();
            done(document.execCommand('copy'));
            document.body.removeChild(ta);
          } catch (e) {
            done(false);
          }
        }
      });
    });
  }
  function toast(message, type, timeout) {
    var host = $('.gh-toasts');
    if (!host) {
      host = document.createElement('div');
      host.className = 'gh-toasts';
      host.setAttribute('role', 'status');
      host.setAttribute('aria-live', 'polite');
      document.body.appendChild(host);
    }
    var el = document.createElement('div');
    el.className = 'gh-toast' + (type ? ' gh-toast--' + type : '');
    el.innerHTML = '<div class="gh-grow">' + esc(message) + '</div><button class="gh-toast__close" type="button" aria-label="关闭">&times;</button>';
    host.appendChild(el);
    var remove = function () {
      el.classList.add('is-leaving');
      setTimeout(function () {
        if (el.parentNode) el.parentNode.removeChild(el);
      }, 200);
    };
    on($('.gh-toast__close', el), 'click', remove);
    setTimeout(remove, timeout || 3200);
    return el;
  }
  function initReveal(root) {
    var els = $$('[data-gh-reveal],.gh-reveal', root);
    if (!els.length) return;
    if (!('IntersectionObserver' in window)) {
      els.forEach(function (el) {
        el.classList.add('is-ready');
      });
      return;
    }
    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-ready');
            io.unobserve(entry.target);
          }
        });
      },
      { rootMargin: '0px 0px -8% 0px', threshold: 0.05 },
    );
    els.forEach(function (el) {
      io.observe(el);
    });
  }
  function initSortable(root) {
    $$('[data-gh-sortable] th[data-sort]', root).forEach(function (th) {
      th.style.cursor = 'pointer';
      th.setAttribute('role', 'button');
      th.setAttribute('tabindex', '0');
      var handler = function () {
        var table = th.closest('table');
        var tbody = $('tbody', table);
        if (!tbody) return;
        var idx = Array.prototype.indexOf.call(th.parentNode.children, th);
        var dir = th.getAttribute('data-dir') === 'asc' ? 'desc' : 'asc';
        $$('th', th.parentNode).forEach(function (o) {
          o.removeAttribute('data-dir');
        });
        th.setAttribute('data-dir', dir);
        var rows = $$('tr', tbody);
        var val = function (tr) {
          var td = tr.children[idx];
          var t = td ? td.getAttribute('data-sort-value') || td.innerText : '';
          return t.trim();
        };
        rows.sort(function (a, b) {
          var x = val(a),
            y = val(b);
          var nx = parseFloat(String(x).replace(/[^\d.-]/g, '')),
            ny = parseFloat(String(y).replace(/[^\d.-]/g, ''));
          var r =
            !isNaN(nx) && !isNaN(ny) && String(x).match(/\d/) && String(y).match(/\d/)
              ? nx - ny
              : String(x).localeCompare(String(y), 'zh-Hans-CN');
          return dir === 'asc' ? r : -r;
        });
        rows.forEach(function (r) {
          tbody.appendChild(r);
        });
      };
      on(th, 'click', handler);
      on(th, 'keydown', function (e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          handler();
        }
      });
    });
  }
  function initToc(root) {
    $$('[data-gh-toc]', root).forEach(function (toc) {
      var links = $$('a[href^="#"]', toc);
      if (!links.length || !('IntersectionObserver' in window)) return;
      var map = {};
      links.forEach(function (a) {
        var id = decodeURIComponent(a.getAttribute('href').slice(1));
        var h = document.getElementById(id);
        if (h) map[id] = a;
      });
      var io = new IntersectionObserver(
        function (entries) {
          entries.forEach(function (entry) {
            if (!entry.isIntersecting) return;
            links.forEach(function (a) {
              a.removeAttribute('aria-current');
            });
            var a = map[entry.target.id];
            if (a) a.setAttribute('aria-current', 'true');
          });
        },
        { rootMargin: '-80px 0px -70% 0px' },
      );
      Object.keys(map).forEach(function (id) {
        io.observe(document.getElementById(id));
      });
    });
  }
  function initForms(root) {
    $$('form[data-gh-submit]', root).forEach(function (form) {
      on(form, 'submit', function () {
        var btn = $('[type="submit"]', form);
        if (!btn || btn.disabled) return;
        btn.disabled = true;
        btn.setAttribute('data-label', btn.innerHTML);
        btn.innerHTML = '<span class="gh-spinner"></span>';
        progress.start();
        setTimeout(function () {
          if (document.body.contains(btn)) {
            btn.disabled = false;
            btn.innerHTML = btn.getAttribute('data-label');
            progress.done();
          }
        }, 8000);
      });
    });
  }
  function initShortcuts() {
    on(document, 'keydown', function (e) {
      if (e.key !== '/' || e.ctrlKey || e.metaKey || e.altKey) return;
      var t = e.target;
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
      var input = $('[data-gh-search] input, input[data-gh-search]');
      if (!input) return;
      e.preventDefault();
      input.focus();
    });
  }
  var SOFT = {
    on: false,
    mainSel: '#main',
    main: null,
    busy: false,
    timeout: 0,
  };
  function softTarget(a) {
    if (!a || !a.getAttribute) return null;
    if (a.target === '_blank' || a.hasAttribute('download') || a.hasAttribute('data-gh-no-soft')) return null;
    var raw = a.getAttribute('href') || '';
    if (!raw || raw.charAt(0) === '#') return null;
    if (/^(mailto:|tel:|javascript:)/i.test(raw)) return null;
    var u;
    try {
      u = new URL(a.href, location.href);
    } catch (e) {
      return null;
    }
    if (u.origin !== location.origin) return null;
    if (u.pathname === location.pathname && u.search === location.search) return null;
    return u;
  }
  function softSwap(doc, nextMain, url) {
    SOFT.main.innerHTML = nextMain.innerHTML;
    SOFT.main.setAttribute('data-gh-page', nextMain.getAttribute('data-gh-page') || '');
    document.title = doc.title;
    var nb = doc.body.getAttribute('class');
    if (nb != null) document.body.setAttribute('class', nb);
    var bp = doc.body.getAttribute('data-gh-page');
    if (bp != null) document.body.setAttribute('data-gh-page', bp);
    var nd = doc.querySelector('meta[name="description"]');
    var cd = document.querySelector('meta[name="description"]');
    if (nd && cd) cd.setAttribute('content', nd.getAttribute('content') || '');
    history.pushState({ ghSoft: 1 }, '', url.href);
    hydrate(SOFT.main);
    syncNavActive();
    var anchor = url.hash ? document.getElementById(decodeURIComponent(url.hash.slice(1))) : null;
    if (anchor) anchor.scrollIntoView();
    else window.scrollTo(0, 0);
    emit('gh:navigated', { url: url.href });
  }
  function softNavigate(target) {
    var url;
    try {
      url = typeof target === 'string' ? new URL(target, location.href) : target;
    } catch (e) {
      location.href = target;
      return;
    }
    if (url.origin !== location.origin) {
      location.href = url.href;
      return;
    }
    if (SOFT.busy) return;
    SOFT.busy = true;
    progress.start();
    SOFT.main.setAttribute('aria-busy', 'true');
    var dim = setTimeout(function () {
      if (SOFT.busy) SOFT.main.setAttribute('data-gh-loading', 'true');
    }, 150);
    var ctrl = 'AbortController' in window ? new AbortController() : null;
    var guard = setTimeout(function () {
      if (ctrl) ctrl.abort();
    }, 8000);
    var settle = function () {
      clearTimeout(dim);
      clearTimeout(guard);
      SOFT.busy = false;
      SOFT.main.removeAttribute('data-gh-loading');
      SOFT.main.removeAttribute('aria-busy');
    };
    fetch(url.href, {
      credentials: 'same-origin',
      headers: { 'X-Requested-With': 'gh-soft', Accept: 'text/html' },
      signal: ctrl ? ctrl.signal : undefined,
    })
      .then(function (res) {
        if (!res.ok) throw new Error('HTTP ' + res.status);
        return res.text().then(function (html) {
          return { html: html, url: new URL(res.url || url.href, location.href) };
        });
      })
      .then(function (r) {
        var doc = new DOMParser().parseFromString(r.html, 'text/html');
        var nextMain = doc.querySelector(SOFT.mainSel);
        if (!nextMain) throw new Error('missing ' + SOFT.mainSel);
        softSwap(doc, nextMain, r.url);
        settle();
        progress.done();
      })
      .catch(function () {
        settle();
        location.href = url.href;
      });
  }
  function initSoftNav() {
    var host = $('[data-gh-soft]');
    if (!host) return;
    SOFT.mainSel = host.getAttribute('data-gh-soft') || '#main';
    SOFT.main = $(SOFT.mainSel);
    if (!SOFT.main || !window.fetch || !window.history || !window.history.pushState || !window.DOMParser) return;
    SOFT.on = true;
    on(document, 'click', function (e) {
      if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
      var a = e.target.closest && e.target.closest('a');
      if (!a) return;
      var u = softTarget(a);
      if (!u) return;
      e.preventDefault();
      a.setAttribute('aria-current', 'page');
      softNavigate(u);
    });
    on(window, 'popstate', function () {
      softNavigate(location.href);
    });
  }
  function hydrate(root) {
    initNav(root);
    initLayers(root);
    initAccordion(root);
    initTabs(root);
    initCopy(root);
    initReveal(root);
    initSortable(root);
    initToc(root);
    initForms(root);
  }
  function boot() {
    var stored = theme.get();
    theme.apply(stored || document.documentElement.getAttribute('data-theme') || 'auto');
    $$('[data-gh-theme-set]').forEach(function (btn) {
      on(btn, 'click', function () {
        theme.set(btn.getAttribute('data-gh-theme-set'));
      });
    });
    $$('[data-gh-theme-cycle]').forEach(function (btn) {
      on(btn, 'click', theme.cycle);
    });
    var mq = window.matchMedia('(prefers-color-scheme: dark)');
    var onSchemeChange = function () {
      if (!theme.get() || theme.get() === 'auto') theme.apply('auto');
    };
    if (mq.addEventListener) mq.addEventListener('change', onSchemeChange);
    else if (mq.addListener) mq.addListener(onSchemeChange);
    hydrate(document);
    syncNavActive();
    on(document, 'keydown', function (e) {
      if (e.key !== 'Escape') return;
      var open = $('.gh-modal[data-open="true"],.gh-drawer[data-open="true"]');
      if (open) closeLayer(open);
      closeAllNav();
      closeAllDropdowns();
    });
    on(document, 'click', function (e) {
      if (!e.target.closest || !e.target.closest('[data-gh-dropdown]')) closeAllDropdowns();
      if (!e.target.closest || !e.target.closest('[data-gh-nav]')) closeAllNav();
    });
    initShortcuts();
    initSoftNav();
    emit('gh:ready', { softNav: SOFT.on });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
  window.GH = {
    theme: theme,
    toast: toast,
    progress: progress,
    openLayer: openLayer,
    closeLayer: closeLayer,
    navigate: softNavigate,
    esc: esc,
  };
})();